// ─── File: RecursionDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.recursion;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RecursionDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build Rajesh's account tree: a parent with two sub-accounts,
        // and one sub-account has a nested sub-account (unknown depth).
        AccountNode root = new AccountNode(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        AccountNode salary = new AccountNode(new Account("SAV2001-S1", "Rajesh Salary", new BigDecimal("50000")));
        AccountNode savings = new AccountNode(new Account("SAV2001-S2", "Rajesh Savings", new BigDecimal("200000")));
        AccountNode nested = new AccountNode(new Account("SAV2001-S2-A", "Rajesh FD", new BigDecimal("75000")));
        savings.addChild(nested);
        root.addChild(salary);
        root.addChild(savings);

        BalanceCalculator calc = new BalanceCalculator();

        // DIRECT RECURSION: total the whole tree regardless of depth.
        BigDecimal total = calc.totalBalance(root);
        log.info(() -> "Rajesh tree total balance Rs." + total);

        // TAIL-RECURSIVE projection for Priya's recurring deposit.
        Account priya = new Account("CUR3001", "Priya", new BigDecimal("250000"));
        BigDecimal projected = calc.projectMonths(priya.getBalance(), new BigDecimal("0.01"), 3);
        log.info(() -> "Priya projected after 3 months at 1% = Rs." + projected);

        // INDIRECT RECURSION demo: isEven calls isOdd and vice versa.
        log.info(() -> "Is 4 even (indirect recursion)? " + calc.isEven(4));
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
}

// ─── Would be in AccountNode.java (tree node) ───
class AccountNode {
    private final Account account;
    private final List<AccountNode> children = new ArrayList<>();
    AccountNode(Account account) { this.account = account; }
    void addChild(AccountNode child) { children.add(child); }
    Account getAccount() { return account; }
    List<AccountNode> getChildren() { return children; }
}

// ─── Would be in BalanceCalculator.java (recursive logic) ───
class BalanceCalculator {
    private static final Logger log = Logger.getLogger("BankLog");

    // DIRECT RECURSION. Base case: a leaf node returns just its own balance.
    // Recursive case: add this node's balance plus the total of every child subtree.
    BigDecimal totalBalance(AccountNode node) {
        BigDecimal sum = node.getAccount().getBalance();
        log.fine(() -> "visiting " + node.getAccount().getAccountId() + " = Rs." + node.getAccount().getBalance());
        for (AccountNode child : node.getChildren()) {
            sum = sum.add(totalBalance(child)); // method calls itself on smaller subtree
        }
        return sum;
    }

    // TAIL RECURSION. The recursive call is the LAST thing done.
    // Base case: months == 0 returns the accumulated balance.
    BigDecimal projectMonths(BigDecimal balance, BigDecimal monthlyRate, int months) {
        if (months == 0) return balance;                 // base case stops recursion
        BigDecimal grown = balance.add(balance.multiply(monthlyRate));
        return projectMonths(grown, monthlyRate, months - 1); // shrinks toward base case
    }

    // INDIRECT RECURSION: isEven and isOdd call each other.
    boolean isEven(int n) { if (n == 0) return true;  return isOdd(n - 1); }
    boolean isOdd(int n)  { if (n == 0) return false; return isEven(n - 1); }
}
